import type { KAPLAYCtx } from "kaplay";
import { HorseState } from "./Horse";

export enum HorseDirection {
	Left = "left",
	Right = "right",
	Down = "down",
	Up = "up",
}

export type HorseSprites = Record<HorseState, Record<HorseDirection, string>>;

const HORSE_STATES: Record<HorseState, { row: number; frames: number }> = {
	[HorseState.Idle]: { row: 0, frames: 3 },
	[HorseState.Eat]: { row: 4, frames: 3 },
	[HorseState.Walk]: { row: 8, frames: 8 },
	[HorseState.Run]: { row: 12, frames: 6 },
	[HorseState.Rear]: { row: 16, frames: 8 },
};

export class SpriteFactory {
	constructor(private k: KAPLAYCtx) {}

	createHorse(variant = 1): HorseSprites {
		if (!Number.isInteger(variant) || variant < 1 || variant > 8) {
			throw new RangeError("Horse variant must be an integer from 1 to 8");
		}
		const sprites = {} as HorseSprites;
		for (const [state, { row, frames }] of Object.entries(HORSE_STATES) as [
			HorseState,
			{ row: number; frames: number },
		][]) {
			sprites[state] = {} as Record<HorseDirection, string>;
			Object.values(HorseDirection).forEach((direction, offset) => {
				const name = `horse-${variant}-${state}-${direction}`;
				const from = (row + offset) * 8;
				this.k.loadSprite(name, `sprites/horse/${variant}.png`, {
					sliceX: 8,
					sliceY: 24,
					anims: {
						[state]: {
							from,
							to: from + frames - 1,
							loop: state !== HorseState.Eat && state !== HorseState.Rear,
							speed: 7,
						},
					},
				});
				sprites[state][direction] = name;
			});
		}
		return sprites;
	}

	createCarrot(): string {
		this.k.loadSprite("carrot", "sprites/carrot-flat.png");
		return "carrot";
	}
}
