import type { GameObj, KAPLAYCtx, Vec2 } from "kaplay";
import { HorseDirection, type HorseSprites } from "./SpriteFactory";
import { HorseNeeds, HORSE_NEEDS_POLICIES, type CareAction, type HorseNeedsPolicy } from "./HorseNeeds";

export enum HorseState {
	Idle = "idle",
	Walk = "walk",
	Run = "run",
	Eat = "eat",
	Rear = "rear",
}

export type HorseRoamingBounds = { left: number; top: number; right: number; bottom: number };

export class Horse {
	private k: KAPLAYCtx;
	private sprites: HorseSprites;
	private state: HorseState = HorseState.Idle;
	private speed = 240;
	private moveTarget: Vec2 | null = null;
	private mouthObj: GameObj;
	private direction = HorseDirection.Right;
	private animatedDirection = HorseDirection.Right;
	private idleTime = 0;
	readonly obj: GameObj;
	readonly needs: HorseNeeds;
	onEatEnd?: (mouthPos: Vec2) => void;

	// Sprite frame is 100x100; all world offsets derive from scale.
	static readonly FRAME_SIZE = 100;
	private readonly scale: number;
	private readonly roamingBounds: () => HorseRoamingBounds;

	constructor(
		k: KAPLAYCtx,
		sprites: HorseSprites,
		pos: Vec2 = k.vec2(120, 80),
		scale = 2,
		policy: HorseNeedsPolicy = HORSE_NEEDS_POLICIES[0],
		roamingBounds: () => HorseRoamingBounds = () => ({ left: 0, top: 0, right: k.width(), bottom: k.height() }),
	) {
		this.k = k;
		this.needs = new HorseNeeds(policy);
		this.sprites = sprites;
		this.scale = scale;
		this.roamingBounds = roamingBounds;
		this.obj = k.add([
			k.pos(pos),
			k.sprite(this.sprites[this.state][this.direction], { anim: this.state, width: Horse.FRAME_SIZE }),
			k.scale(scale),
		]);

		// Collision child at the mouth (local coords are unscaled 0-100).
		this.mouthObj = this.obj.add([
			k.pos(75, 60),
			k.area({ shape: new k.Rect(k.vec2(-8, -8), 16, 16) }),
		]);

		this.obj.onAnimEnd((anim: string) => {
			if (anim === HorseState.Eat) {
				this.onEatEnd?.(this.mouthPos());
				this.setState(HorseState.Idle);
				this.idleTime = this.k.rand(1, 3);
			} else if (anim === HorseState.Rear) {
				this.setState(HorseState.Idle);
				this.idleTime = this.k.rand(1, 3);
			}
		});

		k.onUpdate(() => this.update());
	}

	moveTo(target: Vec2): void {
		// pos is top-left of the scaled sprite; center it on the tap.
		const half = (Horse.FRAME_SIZE * this.scale) / 2;
		this.moveTarget = target.sub(this.k.vec2(half, half));
	}

	fulfillRequest(): CareAction | null {
		const action = this.needs.fulfill();
		if (!action) return null;
		this.moveTarget = null;
		this.idleTime = 3;
		this.setState(action === "feed" ? HorseState.Eat : action === "photo" ? HorseState.Rear : HorseState.Idle);
		return action;
	}

	soothe(): void {
		if (this.state === HorseState.Eat || this.state === HorseState.Rear) return;
		this.moveTarget = null;
		this.idleTime = 3;
		this.setState(HorseState.Idle);
	}

	contains(point: Vec2): boolean {
		const size = Horse.FRAME_SIZE * this.scale;
		return point.x >= this.obj.pos.x + size * 0.15
			&& point.x <= this.obj.pos.x + size * 0.85
			&& point.y >= this.obj.pos.y + size * 0.2
			&& point.y <= this.obj.pos.y + size * 0.85;
	}

	startEating(): void {
		if (this.needs.currentRequest || this.state === HorseState.Eat || this.state === HorseState.Rear) return;
		this.moveTarget = null;
		this.setState(HorseState.Eat);
	}

	isInEatRange(target: GameObj): boolean {
		return this.mouthObj.isOverlapping(target);
	}

	private mouthPos(): Vec2 {
		// Mouth sits bottom-right when facing right, mirrored on flipX.
		return this.obj.pos.add(this.mouthObj.pos.scale(this.scale));
	}

	update(): void {
		const k = this.k;

		const size = Horse.FRAME_SIZE * this.scale;
		const bounds = this.roamingBounds();
		const maxX = Math.max(0, bounds.right - size);
		const maxY = Math.max(0, bounds.bottom - size);
		const minX = Math.min(bounds.left, maxX);
		const minY = Math.min(bounds.top, maxY);
		this.obj.pos.x = k.clamp(this.obj.pos.x, minX, maxX);
		this.obj.pos.y = k.clamp(this.obj.pos.y, minY, maxY);

		if (this.state === HorseState.Eat || this.state === HorseState.Rear) return;

		const previousRequest = this.needs.currentRequest;
		this.needs.update(k.dt());
		if (this.needs.currentRequest) {
			this.moveTarget = null;
			if (!previousRequest) this.setState(HorseState.Rear);
			return;
		}

		if (this.idleTime > 0) {
			this.idleTime -= k.dt();
			return;
		}

		if (!this.moveTarget) {
			const half = size / 2;
			this.moveTo(k.vec2(k.rand(minX, maxX) + half, k.rand(minY, maxY) + half));
		}

		const target = this.moveTarget!;
		target.x = k.clamp(target.x, minX, maxX);
		target.y = k.clamp(target.y, minY, maxY);
		const toTarget = target.sub(this.obj.pos);
		const step = this.speed * k.dt();

		if (toTarget.len() <= Math.max(1, step)) {
			this.obj.pos = target;
			this.moveTarget = null;
			this.idleTime = k.rand(1, 3);
			this.setState(HorseState.Idle);
			return;
		}

		const dir = toTarget.unit();
		this.direction = Math.abs(dir.x) >= Math.abs(dir.y)
			? (dir.x < 0 ? HorseDirection.Left : HorseDirection.Right)
			: (dir.y < 0 ? HorseDirection.Up : HorseDirection.Down);
		const mouthOffsets: Record<HorseDirection, [number, number]> = {
			[HorseDirection.Left]: [25, 60],
			[HorseDirection.Right]: [75, 60],
			[HorseDirection.Down]: [50, 65],
			[HorseDirection.Up]: [50, 40],
		};
		this.mouthObj.pos = k.vec2(...mouthOffsets[this.direction]);
		this.obj.move(dir.scale(this.speed));
		this.setState(HorseState.Walk);
	}

	setState(state: HorseState): void {
		if (!this.sprites[state] || (state === this.state && this.direction === this.animatedDirection)) return;
		this.state = state;
		this.animatedDirection = this.direction;
		this.obj.use(this.k.sprite(this.sprites[state][this.direction], { width: Horse.FRAME_SIZE }));
		this.obj.play(state);
	}
}
