import kaplay from "kaplay";
import { SpriteFactory } from "./SpriteFactory";
import { Horse } from "./Horse";
import { CareRub } from "./CareRub";
import { CARE_ACTIONS, HORSE_NEEDS_POLICIES, type CareAction } from "./HorseNeeds";
// import "kaplay/global"; // uncomment if you want to use without the k. prefix

const k = kaplay({ background: [139, 181, 115] });

k.loadRoot("./"); // A good idea for Itch.io publishing later

const spriteFactory = new SpriteFactory(k);

const horseSprites = Array.from({ length: 8 }, (_, index) => spriteFactory.createHorse(index + 1));
const horses: Horse[] = [];
const horseList = document.querySelector<HTMLUListElement>("#horse-list")!;
const horseCount = document.querySelector<HTMLElement>("#horse-count")!;
const unlockButton = document.querySelector<HTMLButtonElement>("#unlock-horse")!;

const horseSlots = horseSprites.map((_, index) => {
	const item = document.createElement("li");
	item.className = "horse-slot locked";
	const preview = document.createElement("span");
	preview.className = "horse-preview";
	preview.style.backgroundImage = `url(./sprites/horse/${index + 1}.png)`;
	preview.setAttribute("aria-hidden", "true");
	const label = document.createElement("span");
	label.textContent = `Koń ${index + 1}`;
	const status = document.createElement("small");
	status.textContent = "Zablokowany";
	item.append(preview, label, status);
	horseList.append(item);
	return { item, status };
});

function pastureBounds() {
	const canvas = k.canvas.getBoundingClientRect();
	const stable = document.querySelector<HTMLElement>(".stable")!.getBoundingClientRect();
	const panel = document.querySelector<HTMLElement>(".care-panel")!.getBoundingClientRect();
	const xScale = k.width() / Math.max(1, canvas.width);
	const yScale = k.height() / Math.max(1, canvas.height);
	return {
		left: 16 * xScale,
		top: (window.innerWidth < 800 ? stable.bottom - canvas.top + 115 : 115) * yScale,
		right: (window.innerWidth < 800 ? canvas.width - 16 : stable.left - canvas.left - 16) * xScale,
		bottom: (panel.top - canvas.top - 16) * yScale,
	};
}

function unlockHorse(): void {
	const index = horses.length;
	if (index >= horseSprites.length) return;
	const size = Horse.FRAME_SIZE * 2;
	const bounds = pastureBounds();
	const maxX = Math.max(0, bounds.right - size);
	const maxY = Math.max(0, bounds.bottom - size);
	const horse = new Horse(k, horseSprites[index], k.vec2(
		k.rand(Math.min(bounds.left, maxX), maxX),
		k.rand(Math.min(bounds.top, maxY), maxY),
	), 2, HORSE_NEEDS_POLICIES[index], pastureBounds);
	horses.push(horse);
	horseSlots[index].item.classList.remove("locked");
	horseSlots[index].status.textContent = "Na pastwisku";
	horseCount.textContent = `${horses.length} / ${horseSprites.length}`;
	unlockButton.disabled = horses.length === horseSprites.length;
	unlockButton.textContent = unlockButton.disabled ? "Wszystkie konie odblokowane" : "Odblokuj kolejnego konia";
}

k.onLoad(() => {
	unlockHorse();
	setupCarePanel();
	unlockButton.addEventListener("click", unlockHorse);
});

function setupCarePanel(): void {
	const hint = document.querySelector<HTMLElement>("#care-hint")!;
	const counters = new Map(CARE_ACTIONS.map((action) => [action, document.querySelector<HTMLElement>(`[data-count="${action}"]`)!]));
	const tools: Record<CareAction, string> = { pet: "🤚", brush: "🪮", feed: "🥕", photo: "📷" };
	const labels: Record<CareAction, string> = { pet: "Głaskanie", brush: "Szczotkowanie", feed: "Karmienie", photo: "Zdjęcie" };
	const responses: Record<CareAction, string> = {
		pet: "Twój koń cieszy się z głaskania 💕",
		brush: "Sierść lśni! ✨",
		feed: "Smacznego! 🥕",
		photo: "Piękna poza! Zdjęcie zrobione 📷",
	};
	const bubbles = new Map<Horse, HTMLButtonElement>();
	const meters = new Map<Horse, HTMLElement>();
	const rubs = new Map<Horse, CareRub>();
	let activeRub: { horse: Horse; pointerId: number; target: HTMLElement } | null = null;
	const cursors = {} as Record<CareAction, string>;
	for (const action of CARE_ACTIONS) {
		const canvas = document.createElement("canvas");
		canvas.width = 48;
		canvas.height = 48;
		const context = canvas.getContext("2d");
		if (!context) {
			cursors[action] = "pointer";
			continue;
		}
		context.font = '36px "Apple Color Emoji", "Segoe UI Emoji", sans-serif';
		context.textAlign = "center";
		context.textBaseline = "middle";
		context.fillText(tools[action], 24, 24);
		cursors[action] = `url("${canvas.toDataURL()}") 24 24, pointer`;
	}

	function fulfill(horse: Horse): void {
		const action = horse.fulfillRequest();
		if (!action) return;
		rubs.delete(horse);
		const bubble = bubbles.get(horse)!;
		const bounds = bubble.getBoundingClientRect();
		bubble.hidden = true;
		const effect = document.createElement("span");
		effect.className = "care-feedback";
		effect.textContent = { pet: "💕", brush: "✨", feed: "🥕", photo: "📸" }[action];
		if (action === "pet" || action === "brush") {
			effect.textContent = "";
			effect.classList.add("care-progress");
			effect.style.backgroundPosition = "-20px -14px";
		}
		effect.setAttribute("aria-hidden", "true");
		effect.style.left = `${bounds.left + bounds.width / 2}px`;
		effect.style.top = `${bounds.top + bounds.height / 2}px`;
		document.body.append(effect);
		window.setTimeout(() => effect.remove(), 1000);
		hint.textContent = responses[action];
		k.canvas.style.cursor = "default";
		if (action === "photo") {
			const flash = document.createElement("div");
			flash.className = "photo-flash";
			flash.setAttribute("aria-hidden", "true");
			document.body.append(flash);
			window.setTimeout(() => flash.remove(), 400);
		}
	}

	function horseAt(event: PointerEvent): Horse | undefined {
		const bounds = k.canvas.getBoundingClientRect();
		const point = k.vec2(
			(event.clientX - bounds.left) * k.width() / bounds.width,
			(event.clientY - bounds.top) * k.height() / bounds.height,
		);
		return [...horses].reverse().find((horse) => horse.contains(point));
	}

	function stopRub(): void {
		const active = activeRub;
		if (!active) return;
		activeRub = null;
		rubs.get(active.horse)?.stop();
		if (active.target.hasPointerCapture(active.pointerId)) {
			active.target.releasePointerCapture(active.pointerId);
		}
		k.canvas.style.cursor = "default";
	}

	function beginCare(horse: Horse, event: PointerEvent): void {
		if (!event.isPrimary || event.button !== 0 || activeRub) return;
		const action = horse.needs.currentRequest;
		if (!action) return;
		event.preventDefault();
		if (action !== "pet" && action !== "brush") {
			fulfill(horse);
			return;
		}
		const target = event.currentTarget as HTMLElement;
		const rub = rubs.get(horse) ?? new CareRub();
		rubs.set(horse, rub);
		rub.start(event.clientX, event.clientY, event.timeStamp);
		activeRub = { horse, pointerId: event.pointerId, target };
		target.setPointerCapture(event.pointerId);
		k.canvas.style.cursor = cursors[action];
		hint.textContent = "Przytrzymaj i przesuwaj w lewo i prawo przez kilka sekund ↔️";
	}

	k.canvas.style.touchAction = "none";
	k.canvas.addEventListener("pointermove", (event) => {
		if (activeRub) return;
		const action = horseAt(event)?.needs.currentRequest;
		k.canvas.style.cursor = action ? cursors[action] : "default";
	});
	k.canvas.addEventListener("pointerdown", (event) => {
		const horse = horseAt(event);
		if (horse) beginCare(horse, event);
	});
	window.addEventListener("pointermove", (event) => {
		const active = activeRub;
		if (!active || event.pointerId !== active.pointerId) return;
		if ((event.buttons & 1) === 0) {
			stopRub();
			return;
		}
		const action = active.horse.needs.currentRequest;
		if (action !== "pet" && action !== "brush") {
			stopRub();
			return;
		}
		const bubble = bubbles.get(active.horse)!;
		const bounds = bubble.getBoundingClientRect();
		const canvas = k.canvas.getBoundingClientRect();
		const horse = active.horse;
		const x = canvas.left + horse.obj.pos.x / k.width() * canvas.width;
		const y = canvas.top + horse.obj.pos.y / k.height() * canvas.height;
		const width = Horse.FRAME_SIZE * 2 / k.width() * canvas.width;
		const height = Horse.FRAME_SIZE * 2 / k.height() * canvas.height;
		const inside = event.clientX >= Math.min(bounds.left, x) - 32
			&& event.clientX <= Math.max(bounds.right, x + width) + 32
			&& event.clientY >= Math.min(bounds.top, y) - 24
			&& event.clientY <= Math.max(bounds.bottom, y + height) + 24;
		const rub = rubs.get(active.horse)!;
		rub.move(event.clientX, event.clientY, event.timeStamp, inside);
		if (rub.progress >= 1) {
			stopRub();
			fulfill(active.horse);
		}
	});
	for (const type of ["pointerup", "pointercancel", "lostpointercapture"] as const) {
		window.addEventListener(type, (event) => {
			if (event.pointerId === activeRub?.pointerId) stopRub();
		});
	}
	window.addEventListener("blur", stopRub);
	document.addEventListener("visibilitychange", () => {
		if (document.hidden) stopRub();
	});

	k.onUpdate(() => {
		const bounds = k.canvas.getBoundingClientRect();
		const counts: Record<CareAction, number> = { pet: 0, brush: 0, feed: 0, photo: 0 };
		for (const [index, horse] of horses.entries()) {
			let bubble = bubbles.get(horse);
			if (!bubble) {
				bubble = document.createElement("button");
				bubble.type = "button";
				bubble.className = "horse-request";
				bubble.hidden = true;
				const icon = document.createElement("span");
				icon.className = "request-icon";
				icon.setAttribute("aria-hidden", "true");
				const meter = document.createElement("span");
				meter.className = "care-progress";
				meter.setAttribute("role", "progressbar");
				meter.setAttribute("aria-label", "Postęp opieki");
				meter.setAttribute("aria-valuemin", "0");
				meter.setAttribute("aria-valuemax", "100");
				bubble.append(icon, meter);
				meters.set(horse, meter);
				bubble.addEventListener("pointerdown", (event) => beginCare(horse, event));
				bubble.addEventListener("click", (event) => {
					if (event.detail !== 0) return;
					const action = horse.needs.currentRequest;
					if (action === "pet" || action === "brush") {
						hint.textContent = "Przytrzymaj konia lub dymek i przesuwaj w lewo i prawo ↔️";
					} else if (action) {
						fulfill(horse);
					}
				});
				document.body.append(bubble);
				bubbles.set(horse, bubble);
			}
			const action = horse.needs.currentRequest;
			bubble.hidden = !action;
			horseSlots[index].status.textContent = action ? labels[action] : "Na pastwisku";
			if (!action) continue;
			counts[action]++;
			bubble.querySelector<HTMLElement>(".request-icon")!.textContent = tools[action];
			const needsRub = action === "pet" || action === "brush";
			const meter = meters.get(horse)!;
			meter.hidden = !needsRub;
			const progress = rubs.get(horse)?.progress ?? 0;
			const hearts = progress > 0 ? Math.ceil(progress * 6) : 0;
			meter.style.backgroundPosition = `-20px -${14 + (6 - Math.max(1, hearts)) * 48}px`;
			meter.style.filter = hearts === 0 ? "grayscale(1)" : "none";
			meter.style.opacity = hearts === 0 ? "0.5" : "1";
			meter.setAttribute("aria-valuenow", String(Math.round(progress * 100)));
			bubble.classList.toggle("is-rubbing", activeRub?.horse === horse);
			if (activeRub?.horse === horse) {
				hint.textContent = `${labels[action]}: ${Math.round(progress * 100)}% — przesuwaj w lewo i prawo ↔️`;
			}
			bubble.setAttribute("aria-label", `Koń ${index + 1}: ${labels[action]}. ${needsRub ? "Przytrzymaj i przesuwaj w lewo i prawo." : "Kliknij, aby pomóc."}`);
			bubble.style.cursor = cursors[action];
			bubble.style.left = `${k.clamp(bounds.left + (horse.obj.pos.x + Horse.FRAME_SIZE) / k.width() * bounds.width, 110, window.innerWidth - 110)}px`;
			bubble.style.top = `${Math.max(needsRub ? 115 : 70, bounds.top + (horse.obj.pos.y + 10) / k.height() * bounds.height)}px`;
		}
		for (const action of CARE_ACTIONS) {
			counters.get(action)!.textContent = String(counts[action]);
			counters.get(action)!.closest(".care-action")!.classList.toggle("has-requests", counts[action] > 0);
		}
	});
}
