export const CARE_ACTIONS = ["pet", "brush", "feed", "photo"] as const;
export type CareAction = typeof CARE_ACTIONS[number];
export type HorseNeedsPolicy = Readonly<Record<CareAction, number>>;

export const HORSE_NEEDS_POLICIES: readonly HorseNeedsPolicy[] = [
	{ pet: 50, brush: 50, feed: 0, photo: 0 },
	{ pet: 42, brush: 20, feed: 34, photo: 48 },
	{ pet: 36, brush: 46, feed: 16, photo: 54 },
	{ pet: 40, brush: 32, feed: 44, photo: 18 },
	{ pet: 22, brush: 26, feed: 48, photo: 42 },
	{ pet: 48, brush: 24, feed: 20, photo: 38 },
	{ pet: 26, brush: 50, feed: 42, photo: 22 },
	{ pet: 32, brush: 28, feed: 24, photo: 30 },
];

export class HorseNeeds {
	private readonly levels: Record<CareAction, number> = { pet: 0.4, brush: 0.4, feed: 0.4, photo: 0.4 };
	private cooldown = 0;
	private request: CareAction | null = null;

	constructor(readonly policy: HorseNeedsPolicy) {
		for (const action of CARE_ACTIONS) {
			if (!Number.isFinite(policy[action]) || policy[action] < 0) {
				throw new RangeError("Need intervals must be non-negative finite seconds; zero disables a need");
			}
		}
	}

	get currentRequest(): CareAction | null {
		return this.request;
	}

	update(dt: number): void {
		if (!Number.isFinite(dt) || dt <= 0) return;
		this.cooldown = Math.max(0, this.cooldown - dt);
		for (const action of CARE_ACTIONS) {
			if (this.policy[action] > 0) this.levels[action] += dt / this.policy[action];
		}
		if (this.request || this.cooldown > 0) return;
		let mostUrgent: CareAction | null = null;
		for (const action of CARE_ACTIONS) {
			if (this.policy[action] > 0 && this.levels[action] >= 1 && (!mostUrgent || this.levels[action] > this.levels[mostUrgent])) {
				mostUrgent = action;
			}
		}
		this.request = mostUrgent;
	}

	fulfill(): CareAction | null {
		const action = this.request;
		if (!action) return null;
		this.levels[action] = 0;
		this.request = null;
		this.cooldown = 5;
		return action;
	}
}
